resource aks 'Microsoft.ContainerService/managedClusters@2024-02-01' = {
  name: aksName
  location: location
  tags: tags
  sku: {
    name: 'Base'
    tier: 'Paid'
  }
  identity: {
    type: 'SystemAssigned'
  }
  properties: {
    kubernetesVersion: kubernetesVersion != '' ? kubernetesVersion : null
    dnsPrefix: toLower('${substring(aksName, 0, 30)}-${uniqueString(resourceGroup().id)}')
    enableRBAC: true
    aadProfile: {
      managed: true
      enableAzureRBAC: enableAzureRBAC
      adminGroupObjectIDs: adminGroupObjectIds
    }
    apiServerAccessProfile: {
      enablePrivateCluster: true
      privateDNSZone: 'System'
    }
    oidcIssuerProfile: {
      enabled: true
    }
    workloadIdentityProfile: {
      enabled: true
    }
    autoUpgradeProfile: {
      upgradeChannel: 'stable'
    }
    addonProfiles: {
      azurepolicy: {
        enabled: true
      }
      omsagent: {
        enabled: true
        config: {
          logAnalyticsWorkspaceResourceID: logAnalytics.id
        }
      }
    }
    agentPoolProfiles: [
      {
        name: 'systempool'
        mode: 'System'
        type: 'VirtualMachineScaleSets'
        vmSize: systemVMSize
        osType: 'Linux'
        osDiskType: 'Managed'
        osDiskSizeGB: 128
        count: systemNodeCount
        enableAutoScaling: true
        minCount: systemPoolMinCount
        maxCount: systemPoolMaxCount
        vnetSubnetID: aksSubnetId
        maxPods: 50
        availabilityZones: [
          '1'
          '2'
          '3'
        ]
        upgradeSettings: {
          maxSurge: '33%'
        }
        enableNodePublicIP: false
        scaleSetPriority: 'Regular'
        enableEncryptionAtHost: encryptionAtHost
        orchestratorVersion: kubernetesVersion != '' ? kubernetesVersion : null
      }
    ]
    networkProfile: {
      networkPlugin: 'azure'
      networkPolicy: 'azure'
      serviceCidr: serviceCidr
      dnsServiceIP: dnsServiceIP
      dockerBridgeCidr: dockerBridgeCidr
      loadBalancerSku: 'standard'
      outboundType: 'loadBalancer'
      loadBalancerProfile: {
        managedOutboundIPs: {
          count: 2
        }
        allocatedOutboundPorts: 0
        idleTimeoutInMinutes: 30
      }
    }
    disableLocalAccounts: true
    securityProfile: {
      imageCleaner: {
        enabled: true
        intervalHours: 48
      }
    }
  }
}

